        const bestTarget=targetResults.slice().sort((a,b)=>b.profit-a.profit)[0]||null;
        return{site:site,cash:cash,bonusEligible:bonusEligible,bonusDetails:bonusDetails,bonus:bonus,availableSite:availableSite,ratio:ratio,saleFeePercent:saleFeePercent,grossMarket:roundMoney(grossMarket),grossProfit:roundMoney(grossProfitExact),marketFees:roundMoney(marketFees),market:roundMoney(market),cost:roundMoney(costExact),profit:roundMoney(profitExact),charmValue:roundMoney(charmValue),targetSite:roundMoney(targetSite),remainingSite:remainingSite,remainingCash:ratio>0?roundMoney(remainingSite/ratio):0,overspend:remainingSite<0,validTargets:validTargets,incompleteDeposits:incompleteDeposits,incompleteTargets:incompleteTargets,bestTarget:bestTarget,targetResults:targetResults};
