        const profitColor=t.profit>0?'var(--green)':t.profit<0?'var(--red)':'var(--text)';$('#sum-margin').style.color=profitColor;$('#sum-profit').style.color=profitColor;$('#quick-profit').style.color=profitColor;$('#quick-balance').style.color=t.overspend?'var(--red)':'var(--text)';$('#sum-gross-profit').style.color=t.grossProfit>0?'var(--accent)':t.grossProfit<0?'var(--red)':'var(--text)';$('#savebar-profit').style.color=profitColor;$('#sum-site-remaining').style.color=t.overspend?'var(--red)':'var(--text)';
