        const progress=$('#bonus-progress'),progressBar=progress.parentElement,details=t.bonusDetails;progress.style.width=(details.progress*100)+'%';progressBar.setAttribute('aria-valuenow',String(Math.round(details.progress*100)));$$('.bonus-tier').forEach(el=>{const threshold=Number(el.dataset.threshold);el.classList.toggle('reached',t.site>=threshold);el.classList.toggle('current',details.currentThreshold===threshold)});
