        if(filter==='profit')filtered=filtered.filter(t=>Number(t.profit)>0);if(filter==='loss')filtered=filtered.filter(t=>Number(t.profit)<0);if(filter==='break-even')filtered=filtered.filter(t=>Number(t.profit)===0);if(filter==='pending')filtered=filtered.filter(t=>asDate(t.unlockAt).getTime()>now);if(filter==='ready')filtered=filtered.filter(t=>asDate(t.unlockAt).getTime()<=now);
        const sort=$('#history-sort').value;const unlockOrder=t=>{const value=asDate(t.unlockAt).getTime();return value<=now?Number.MAX_SAFE_INTEGER:value};filtered=filtered.slice().sort((a,b)=>sort==='profit-high'?(Number(b.profit)||0)-(Number(a.profit)||0):sort==='profit-low'?(Number(a.profit)||0)-(Number(b.profit)||0):sort==='margin-high'?(Number(b.margin)||0)-(Number(a.margin)||0):sort==='unlock-soon'?unlockOrder(a)-unlockOrder(b):asDate(b.createdAt)-asDate(a.createdAt));
        const list=$('#history-list');list.replaceChildren();filtered.forEach(t=>list.appendChild(makeTradeCard(t)));$('#history-empty').hidden=filtered.length>0;$('#history-stat-count').textContent=String(filtered.length);const totalProfit=filtered.reduce((s,t)=>s+(Number(t.profit)||0),0);$('#history-stat-profit').textContent=(totalProfit>=0?'+':'')+money(totalProfit);const best=filtered.length?filtered.reduce((value,t)=>Math.max(value,Number(t.profit)||0),-Infinity):0;$('#history-stat-best').textContent=(best>0?'+':'')+money(best);const avgMargin=filtered.length?filtered.reduce((sum,t)=>sum+(Number(t.margin)||0),0)/filtered.length:0;$('#history-stat-margin').textContent=filtered.length?pct(avgMargin):'—';$('#history-stat-pending').textContent=String(filtered.filter(t=>asDate(t.unlockAt).getTime()>now).length);renderProfitChart(filtered)
